        // managed server-side via indexing policy). Remove HasIndex calls.
        // modelBuilder.Entity<Blog>().HasIndex(b => b.Name); // REMOVED

        // Breaking change 2: Discriminator property renamed from "Discriminator" to "$type".
        // To stay compatible with existing documents, explicitly set the old name.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 3: Id format changed from "EntityType|Key" to just the key.
        // To read existing "Blog|1"-style documents, restore the old id factory.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // If configuring here, opt back into the legacy id format for existing data:
        // optionsBuilder.UseCosmos(..., cosmosOptions =>
        // {
        //     // No built-in flag; see id-property mapping below.
        // });
    }
}

