using Microsoft.EntityFrameworkCore;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var blog = modelBuilder.Entity<Blog>();

        // FIX 1 – Discriminator property renamed "$type" in EF 9.
        // Existing documents use "Discriminator", so pin the old name.
        blog.HasDiscriminator<string>("Discriminator");

        // FIX 2 – HasIndex is no longer supported for Cosmos (server-side concern).
        // REMOVED: blog.HasIndex(b => b.Name);

        // FIX 3 – Id format changed from "EntityType|Key" to just the key.
        // Map the JSON "id" property explicitly so EF can read existing "Blog|1" ids.
        blog.ToContainer("Blogs");
        blog.HasPartitionKey(b => b.Id);
        blog.Property(b => b.Id)
            .ToJsonProperty("id");
    }
}

class Blog
{
    public string Id { get; set; }
    public string Name { get; set; }
}

